dec_med = exp (-3/fps);
dec_slow = exp (-.3/fps);

beat = bass+mid+treb; 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .5+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %8;

q20 = avg;
q21 = beat;
q22 = peak;
q23 = index;
q24 = is_beat;
q26 = bass + mid + treb;

k1 =  is_beat*equal(index,0);
p1 =  k1*(p1+1) + (1-k1)*p1;

p2 = dec_med * p2+ (1-dec_med)*p1;
p3 = dec_med * p3+ (1-dec_med)*p2;
rott = p3 * 3.1416/2;
q27 = index + 1;

movz = movz + .006*30/fps*(1.5+sin(rott));
q29 = movz ;


movx = movx + .01*30/fps*(sin(time/5));
q28 = movx;


q30 = sin(time/9)+2;

