float3 ret1, tree;
float mask1;

shader_body {
float corr = texsize.xy*texsize_noise_hq.zw * 0.05;
float2 uv1 = float2(uv.x-0.5,uv.y-0.5)*aspect.xy;

float2 uv3 = uv1;
float dist = 60;

uv3 = dist * uv1;

float zu = lum(tex2D (sampler_noise_lq,uv));
float shape = 40* (q29+2);
float ky = saturate(-uv3.y/50+zu/8*cos(16*zu)+.2);
//Faktor an uv.y drehen

float k1 = uv3.x*(2-.3*uv.y);;

k1 = k1 - sign (k1)*24; //Verdoppelung
k1 = k1 - sign (k1)*9; //Verdoppelung

int n = 1 ;
float delta = .1;
while (n <= 5) 
{
  k1 += 2*(k1-6*n*sign(k1))*ky;
  //Mult. mit n steuert "Breitenwuchs"
  ky = saturate (ky - delta);
  delta *= 1;
  //delta ist vertikaler Verzweig. abstand
  n++; 
}

k1 = clamp(k1,-1.6,1.6);

float2 rs1 = float2 (tan(k1),uv3.y);

tree = lum(tex2D(sampler_noise_hq,rs1*corr))+.2;
//tree = abs(cos(k1));
